DE_FABRICA = (("instalacion", "Instalacion"),
              ("correctivo", "Correctivo"),
              ("trabajos", "Trabajos"))


def sembrar(apps, schema_editor):
    #  El normalizador de las plantillas, el mismo de siempre (es una funcion
    #  pura: no depende de ningun modelo).
    from campo.plantillas import normalizar_asunto

    Org = apps.get_model("common", "Org")
    Labor = apps.get_model("campo", "Labor")
    AsuntoDeLabor = apps.get_model("campo", "AsuntoDeLabor")
    WorkType = apps.get_model("campo", "WorkType")
    Configuracion = apps.get_model("campo", "ConfiguracionDeReparto")

    for org in Org.objects.all():
        viejos = (Configuracion.objects.filter(org=org)
                  .values_list("nombres_de_labor", flat=True).first())
        viejos = viejos if isinstance(viejos, dict) else {}
        por_codigo = {}
        for codigo, nombre in DE_FABRICA:
            labor, _ = Labor.objects.get_or_create(
                org=org, codigo=codigo,
                defaults={"de_fabrica": True,
                          "nombre": (str(viejos.get(codigo) or "").strip()
                                     or nombre)[:40]})
            por_codigo[codigo] = labor

        vistos = set(AsuntoDeLabor.objects.filter(org=org)
                     .values_list("normalizado", flat=True))
        for tipo in (WorkType.objects.filter(org=org).exclude(labor="")
                     .order_by("codigo")):
            labor = por_codigo.get(tipo.labor)
            if labor is None:
                continue
            for asunto in (tipo.asuntos or []):
                normalizado = normalizar_asunto(asunto)
                if not normalizado or normalizado in vistos:
                    continue
                vistos.add(normalizado)
                AsuntoDeLabor.objects.create(
                    org=org, labor=labor, asunto=str(asunto)[:255],
                    normalizado=normalizado)


